effect.shader:

    vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
    mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
    vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
    #define fragCoord gl_FragCoord.xy

   /////////////////////////



   /////////////////////////
   void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 image_size = getTexSize(inputImg.size);
        vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
        vec2 iMouse = vec2(0.5, 0.5);
        vec2 TanRyu;
        TanRyu = acScreenNorm; 

        /////////////////////////

    	vec4 fragColor;

	vec4 col = texture2DCv(inputImg.texture, acScreenNorm.st);
	vec4 lightValues;
	vec4 paramWeights;

	float lum = (col.r + col.g + col.b) / 3.0;

	lightValues.x = lum;
	lightValues.y = lum;
	lightValues.z = 1.0 - lum;
	lightValues.w = 1.0 - lum;
	lightValues.xz = (lightValues.xz - 0.25)*1.3333334;
	lightValues.yw = 2.0*(lightValues.yw - 0.5);

	lightValues = max(lightValues,0.0)*1.5;
	lightValues = (3.0 - 2.0*lightValues)*lightValues*lightValues;

	paramWeights.x = lights*lights*sign(lights);
	paramWeights.y = highlights*highlights*sign(highlights);
	paramWeights.z = shadows*shadows*sign(shadows);
	paramWeights.w = darks*darks*sign(darks);

	float sum = abs(paramWeights.x) + abs(paramWeights.y) + abs(paramWeights.z) + abs(paramWeights.w) + 1.0;

	col.rgb += dot(lightValues,paramWeights)/sum;

	fragColor.rgb = min(col.rgb,col.a);
	fragColor.a = col.a;

    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        resultfinal = factor * texColor.a;

    	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
    	// }
    }
